import sys
from collections import defaultdict, deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    names = input_data[1:n+1]

    graph = defaultdict(set)
    in_degree = {chr(ord('a') + i): 0 for i in range(26)}

    # Build the graph based on lexicographical constraints
    for i in range(n - 1):
        s1 = names[i]
        s2 = names[i+1]

        min_len = min(len(s1), len(s2))
        found_diff = False

        for j in range(min_len):
            if s1[j] != s2[j]:
                # s1[j] must come before s2[j]
                u, v = s1[j], s2[j]
                if v not in graph[u]:
                    graph[u].add(v)
                    in_degree[v] += 1
                found_diff = True
                break

        if not found_diff:
            # If no difference found, then s1 must be a prefix of s2
            # If s1 is longer than s2, it's impossible
            if len(s1) > len(s2):
                print("Impossible")
                return

    # Topological sort using Kahn's algorithm
    queue = deque()
    for char in in_degree:
        if in_degree[char] == 0:
            queue.append(char)

    result = []
    while queue:
        u = queue.popleft()
        result.append(u)

        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(result) < 26:
        print("Impossible")
    else:
        print("".join(result))

if __name__ == "__main__":
    solve()
